/* trx_addons-icons-css */
@font-face {
  font-family: 'trx_addons_icons';
  src: url("../fonts/ext/972212b2-trx_addons_icons.eot");
  src: url("../fonts/ext/972212b2-trx_addons_icons.eot") format('embedded-opentype'),
       url("../fonts/ext/de52271d-trx_addons_icons.woff2") format('woff2'),
       url("../fonts/ext/01acd3d2-trx_addons_icons.woff") format('woff'),
       url("../fonts/ext/d5e64802-trx_addons_icons.ttf") format('truetype'),
       url("../fonts/ext/ef2e618e-trx_addons_icons.svg") format('svg');
  font-weight: normal;
  font-style: normal;
}
/* Chrome hack: SVG is rendered more smooth in Windozze. 100% magic, uncomment if you need it. */
/* Note, that will break hinting! In other OS-es font will be not as sharp as it could be */
/*
@media screen and (-webkit-min-device-pixel-ratio:0) {
  @font-face {
    font-family: 'trx_addons_icons';
    src: url("../fonts/ext/ef2e618e-trx_addons_icons.svg") format('svg');
  }
}
*/
[class^="trx_addons_icon-"]:before, [class*=" trx_addons_icon-"]:before {
  font-family: "trx_addons_icons";
  font-style: normal;
  font-weight: normal;
  speak: never;

  display: inline-block;
  text-decoration: inherit;
  width: 1em;
  margin-right: .2em;
  text-align: center;
  /* opacity: .8; */

  /* For safety - reset parent styles, that can break glyph codes*/
  font-variant: normal;
  text-transform: none;

  /* fix buttons height, for twitter bootstrap */
  line-height: 1em;

  /* Animation center compensation - margins should be symmetric */
  /* remove if not needed */
  margin-left: .2em;

  /* you can be more comfortable with increased icons size */
  /* font-size: 120%; */

  /* Font smoothing. That was taken from TWBS */
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  /* Uncomment for 3D effect */
  /* text-shadow: 1px 1px 1px rgba(127, 127, 127, 0.3); */
}

