/* quiz-maker-css */
/**
 * All of the CSS for your public-facing functionality should be
 * included in this file.
 */
.ays-quiz-container {
    box-sizing: border-box;
}
.ays-quiz-container p {
    padding: 0 10px;
    margin: 1em 0;
}
.ays-quiz-container section.ays_quiz_redirection_timer_container,
.ays-quiz-container section.ays_quiz_timer_container {
    padding-top: 5px;
}
.ays-quiz-container section.ays_quiz_redirection_timer_container hr,
.ays-quiz-container section.ays_quiz_timer_container hr{
    padding: 0px;
    margin: 0px;
    border-bottom-color: #ccc;
}

.ays-quiz-container form span {
    margin-top: 0;
    margin: 0;
}
.ays-field {
    display: flex;
	text-align: left;
    opacity: 1;
    margin-bottom: 10px;
    position: relative;

}
[id^="ays-quiz-container-"] .ays-field input[type='checkbox'],
[id^="ays-quiz-container-"] .ays-field input[type='radio']{
	display: none!important;
}
.ays-quiz-answers .ays-field input~label[for^="ays-answer-"] {
    font-weight: 600;
    color: #484848;
    margin-bottom: 0;
    width: 100%;
    height: unset;
    transition: all .3s;
    cursor: pointer;
    display: block !important;
    padding: 10px;
    word-wrap: break-word !important;
    white-space: initial !important;
    line-height: 33px;
    text-transform: initial;
    max-width: 100%;
    margin: 0!important;
    letter-spacing: unset;
}
.ays-quiz-answers .ays-field input~label.ays_answer_image_label[for^="ays-answer-"] {
    line-height: 0 !important;
}
.ays-quiz-answers .ays-field input[type="checkbox"]+label[for^="ays-answer-"] {
	margin-left: 0;
}

.ays-field.ays_list_view_item input~label:before {
	content: "";
	display: inline-block;
	background: #ddd;
	background-clip: content-box;
	width: 20px;
	height: 20px;
	border: 3px solid #ccc;
	padding: 3px 3px 3px 3px;
	box-sizing: border-box;
	transition: all .4s linear;
	vertical-align: middle;
	margin-right: 10px;
	position: unset;
}
.ays-field.ays_list_view_item input[type="radio"]~label:before {
	border-radius: 50%;
}
.ays-field.ays_list_view_item input~label:hover:before {
	background: #ddd;
	color: #ddd;
	background-clip: content-box;
}
.ays-field input~label:hover {
    opacity: 1 !important;
}

.ays-quiz-container .select2-container {
	display: block;
	width: 100%!important;
}
.ays-quiz-container .select2.select2-container .select2-selection {
    padding: 0 !important;
}
.ays-quiz-container .select2-container .select2-selection--single,
.ays-quiz-container .select2-container--default .select2-selection--single .select2-selection__rendered {
	height: 40px;
	line-height: 40px;
	font-size: 17px !important;
    width: 100%;
    color: white;
    display: inline-block;
}
.ays-quiz-container .select2-container--default,
.ays-quiz-container .select2-container--default .selection,
.ays-quiz-container .select2-container--default .select2-selection {
    display: inline-block;
    width: 100%;
    height: 40px;
}

div.ays-quiz-container[id^="ays-quiz-container-"] .select2-container--default .select2-selection {
    display: inline-block;
    width: 100%;
    height: 40px;
}

.ays-quiz-container .select2-container--default .select2-selection--single {
	background: transparent;
	border: none;
	border-radius: unset;
}
.ays-quiz-container .select2-container--default .select2-selection--single:focus {
	outline: none;
	box-shadow: none;
}
.ays-quiz-container .select2-container .select2-selection--single .select2-selection__arrow b[role="presentation"] {
	border: none;
}
.ays-quiz-container .select2-container--default .select2-selection--single .select2-selection__arrow {
	top: 0;
	right: 10px;
    color: #fff;
}

div.ays-quiz-container[id^="ays-quiz-container-"] .select2-container--default .select2-selection--single .select2-selection__arrow {
	height: 26px;
    top: 1px;
    right: 10px;
    transform: unset;
}

div.ays-quiz-container[id^="ays-quiz-container-"] .select2-container--default .select2-selection--single .select2-selection__arrow b {
    display: inline-block;
}


[id^="ays-quiz-container-"] * {
	box-sizing: border-box;
    word-wrap: break-word;
}


div.ays-quiz-wrap {
    max-width: 100%;
    width: 100%;
}

div.ays-quiz-container[id^="ays-quiz-container-"] p:empty{
	display: none;
}

div.ays-quiz-container[id^="ays-quiz-container-"] {
	width: 96%;
    min-width: 200px;
    max-width: 96%;
	margin: 20px auto;
	text-align: center;
	background: white;
	border: 0 none;
