/*
 * User reports info table .
 * The Modal (background) */
.ays-modal {
    display: none;
    position: fixed;
    left: 0;
    top: 0;
    z-index: 1000000 !important;
    width: 100%;
    height: 100%;
    animation-duration: .5s;
    transition: .5s ease-in-out;
    outline: 0;
}

.ays-modal {
    overflow-x: hidden;
    overflow-y: auto;
}

.modal-open {
    overflow: hidden;
    position: relative;
    height: 100%;
}

.ays-modal-backdrop {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 99999 !important;
    background-color: rgba(0, 0, 0, 0.5);
}
/* Modal Content/Box */
.ays-modal-content {
    background-color: #fefefe;
    margin: auto; /* 15% from the top and centered */
    margin-bottom: 30px;
    margin-top: 40px;
    border: 1px solid #888;
    width: 85%; /* Could be more or less, depending on screen size */
    z-index: 100000000;
    position: relative;
    padding-left: 0 !important;
    animation-duration: .3s;
    transition: .5s ease-in-out;
    border-radius: 4px;
}

#ays-results-modal .ays-modal-content {
    min-height: 500px;
    margin: auto !important; /* 15% from the top and centered */
    margin-bottom: 30px !important;
    margin-top: 40px !important;
}
/* The Close Button */
.ays-close {
    color: #aaa;
    float: right;
    line-height: 1.3;
    font-size: 28px;
    font-weight: bold;
}

.ays-close:hover,
.ays-close:focus {
    color: black;
    text-decoration: none;
    cursor: pointer;
}

.ays-modal-header {
    padding: 4px 16px;
}
