/* Utils */
.clearfix:after,
.container:after,
.container-fluid:after,
.row:after {
  content: " ";
  clear: both;
  width: 100%;
  height: 0;
  display: block;
}

.center-block {
  display: block;
  margin-left: auto;
  margin-right: auto;
}

.pull-right {
  float: right !important;
}

.pull-left {
  float: left !important;
}

.affix {
  position: fixed;
  -webkit-transform: translate3d(0, 0, 0);
  -ms-transform: translate3d(0, 0, 0);
  transform: translate3d(0, 0, 0);
}

.visible {
  visibility: visible;
}

.invisible {
  visibility: hidden;
}

.show {
  display: block !important;
}

.hide {
  display: none !important;
}

.hidden {
  display: none !important;
  visibility: hidden !important;
}

.text-hide {
  font-size: 0;
  line-height: 0;
  color: transparent;
  text-shadow: none;
  background-color: transparent;
  border: 0;
}

.vertical-centered {
  overflow: hidden;
}

.vertical-centered:before {
  content: ' ';
  width: 0;
  height: 100%;
  margin-left: -0.3em;
}

.vertical-centered:before,
.vertical-centered > * {
  display: inline-block;
  vertical-align: middle;
}

.qwery_loading,
.trx_addons_loading {
  background-image: url("../images/ext/bb9907cf-preloader.png") !important;
