    font-family: 'sofia-pro';
  
    color: #040405;
}

.div-meta-group {
   
    font-family: 'sofia-pro';
    font-weight: 400;
    color: #88919F;
}

.session-column {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    padding: 15px 0;
    padding-left: 50px;
}
span.meta-date-range:before {
    font-size: 16px !important;
    font-family: "fontello";
    content: '\E9B7';
    margin: 0;
    color: #0063dc;
}
.d-shortcode-sc span.sc_button_title {
    color:#0063dc;
}


.col-three.session-item {
    width: 30%;
}
.col-two.session-item {
    width: 55%;
}

.col-one.session-item {
    width: 100px;
}
.sessions-container {
    padding-top: 10px;
}
a#load-more:hover *,
a#load-more.loading * {
    color: #fff !important;
}

.col-one.session-item span {
    display: block;
    font-size: 16px;
    line-height: 17px;
    font-weight: 500;
    letter-spacing: 1px;
    color: var(--theme-color-text_dark);
    text-transform: uppercase;
}

a#load-more .sc_button_text:before {
    content:"";
    border: 4px solid rgba(0, 0, 0, 0.1);
    border-radius: 50%;
    border-top: 4px solid #3498db;
    width: 20px;
    height: 20px;
    animation: spin 1s linear infinite;
    animation: spin 1s linear infinite;
    margin: 0 auto;
    position: absolute;
    opacity: 0;
    visibility: hidden;
    left: 0;
    right: 0;

}
a#load-more.loading {
    color: #fff !important;
    border-color: var(--theme-color-text_dark_blend);
    background-color: var(--theme-color-text_dark_blend) !important;
}

a#load-more.loading .sc_button_text:before {
    visibility: visible;
    opacity: 1;
    z-index: 99;;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

span.meta-date-range {
    font-size: 14px;
    text-transform: capitalize;
}
/* .col-two.session-item h4 {
    font-size: 25px;
    margin-top: 5px;
    margin-bottom: 15px;
    color: #454A53;
    display: flex;
    flex-wrap: wrap;
  
    text-transform: capitalize;
    font-family: 'sofia-pro';
    font-weight: 600;
    color: #040405;
} */

.session-meta {
    font-weight: 500;
    color: var(--theme-color-text_dark);
    margin-bottom: 15px;
}

.col-one.session-item {
    text-align: center;

}
.col-one.session-item strong {
    font-weight: bold;
    font-size: 25px;
    color: var(--theme-color-text_dark);
}
section.trainings_page_sessions h2 {
    padding-bottom: 20px;
}
.paginate-container a:not(.prev,.next),
.paginate-container span.page-numbers.current{
    display: none;
}

a.next.page-numbers:after {
    position: relative;
    top: 2px;
    content: '\E9DF';
    font-family: fontello;
    font-size: 12px;
    line-height: 1em;
    font-weight: 400;
    margin-left: 0.9em;
    background-image: none!important;
    width: auto;
    height: auto;
    padding-right: 1px;
}
a.prev.page-numbers:before {
    position: relative;
    top: 2px;
    content: '\EA07';
    font-family: fontello;
    font-size: 12px;
    line-height: 1em;
    font-weight: 400;
    margin-right: 0.9em;
    background-image: none!important;
    width: auto;
    height: auto;
    padding-left: 1px;
}

.paginate-container {
    display: flex;
    align-items: center;
    font-weight: 500;
    justify-content: space-between;
    margin-top: 30px;
    border-top: solid 1px #ddd;
    padding-top: 30px;
}
.d-shortcode-sc.loading {
    opacity: 0.3;
}
.paginate-container a {
    display: inline-flex;
    align-items: center;
}

a.disable.page-numbers {
    pointer-events: none;
    opacity: 0.4;
}


@media (max-width:900px){
    .d-info.col {
        width: calc(100% / 2 - 30px);
    }
    .traning-meta h4 {
       
        margin-top: 0;
      
    }
        .traning-meta {
        padding-bottom: 0;
    }
    .d.info p {
        margin-bottom: 10px;
    }


}

@media (max-width:768px){
    .col-two.session-item {
        width: calc(100%);
        
        /* order: 3; */
    }
    .col-one.session-item {
        width: 100px;
    }
    h4.ss_month-separator-text:after{
        width: calc(100% - 200px);
    }
    .col-three.session-item {
        /* width: calc(100% - 70px); */
        /* order: 2; */
    }
    .session-column{
        padding-left: 25px;
    }
}

@media (max-width:600px){
    .d-info.col {
        width: calc(100% );
    }
}

